gaeC(){return"\u03a4\u03bf KitchenFlow \u03b4\u03b5\u03bd \u03b1\u03c0\u03bf\u03c4\u03b5\u03bb\u03b5\u03af \u03c0\u03b9\u03c3\u03c4\u03bf\u03c0\u03bf\u03b9\u03b7\u03bc\u03ad\u03bd\u03b7 \u03c6\u03bf\u03c1\u03bf\u03bb\u03bf\u03b3\u03b9\u03ba\u03ae \u03c4\u03b1\u03bc\u03b5\u03b9\u03b1\u03ba\u03ae \u03bc\u03b7\u03c7\u03b1\u03bd\u03ae \u03ba\u03b1\u03b9 \u03b4\u03b5\u03bd \u03b4\u03b9\u03b1\u03b2\u03b9\u03b2\u03ac\u03b6\u03b5\u03b9 \u03b4\u03b5\u03b4\u03bf\u03bc\u03ad\u03bd\u03b1 \u03c3\u03b5 \u03ba\u03b1\u03bc\u03af\u03b1 \u03c6\u03bf\u03c1\u03bf\u03bb\u03bf\u03b3\u03b9\u03ba\u03ae \u03b1\u03c1\u03c7\u03ae (\u03c0.\u03c7. \u0391\u0391\u0394\u0395/myDATA). \u039b\u03b5\u03b9\u03c4\u03bf\u03c5\u03c1\u03b3\u03b5\u03af \u03c9\u03c2 \u03c8\u03b7\u03c6\u03b9\u03b1\u03ba\u03cc \u03c3\u03b7\u03bc\u03b5\u03b9\u03c9\u03bc\u03b1\u03c4\u03ac\u03c1\u03b9\u03bf \u03b3\u03b9\u03b1 \u03c4\u03b7 \u03bb\u03ae\u03c8\u03b7 \u03c0\u03b1\u03c1\u03b1\u03b3\u03b3\u03b5\u03bb\u03b9\u03ce\u03bd \u03ba\u03b1\u03b9 \u03c4\u03b7\u03bd \u03b5\u03c3\u03c9\u03c4\u03b5\u03c1\u03b9\u03ba\u03ae \u03c0\u03b1\u03c1\u03b1\u03ba\u03bf\u03bb\u03bf\u03cd\u03b8\u03b7\u03c3\u03b7 \u03c0\u03bb\u03b7\u03c1\u03c9\u03bc\u03ce\u03bd \u2014 \u03c0\u03b1\u03c1\u03b1\u03bc\u03ad\u03bd\u03b5\u03c4\u03b5 \u03c5\u03c0\u03b5\u03cd\u03b8\u03c5\u03bd\u03bf\u03b9 \u03b3\u03b9\u03b1 \u03c4\u03b7\u03bd \u03ad\u03ba\u03b4\u03bf\u03c3\u03b7 \u03c4\u03c9\u03bd \u03b1\u03c0\u03b1\u03b9\u03c4\u03bf\u03cd\u03bc\u03b5\u03bd\u03c9\u03bd \u03b1\u03c0\u03cc \u03c4\u03bf\u03bd \u03bd\u03cc\u03bc\u03bf \u03b1\u03c0\u03bf\u03b4\u03b5\u03af\u03be\u03b5\u03c9\u03bd/\u03c4\u03b9\u03bc\u03bf\u03bb\u03bf\u03b3\u03af\u03c9\u03bd \u03bc\u03ad\u03c3\u03c9 \u03c4\u03bf\u03c5 \u03c0\u03b9\u03c3\u03c4\u03bf\u03c0\u03bf\u03b9\u03b7\u03bc\u03ad\u03bd\u03bf\u03c5 \u03c3\u03b1\u03c2 \u03c3\u03c5\u03c3\u03c4\u03ae\u03bc\u03b1\u03c4\u03bf\u03c2."},
gaeF(){return"\u0391\u03c0\u03bf\u03b8\u03ae\u03ba\u03b5\u03c5\u03c3\u03b7 \u03b1\u03bb\u03bb\u03b1\u03b3\u03ce\u03bd"},
gaeG(){return"\u03a4\u03bf \u03c0\u03c1\u03bf\u03c6\u03af\u03bb \u03b5\u03c0\u03b9\u03c7\u03b5\u03af\u03c1\u03b7\u03c3\u03b7\u03c2 \u03b1\u03c0\u03bf\u03b8\u03b7\u03ba\u03b5\u03cd\u03c4\u03b7\u03ba\u03b5"},
gaen(){return"\u0392\u03c1\u03b5\u03c4\u03b1\u03bd\u03b9\u03ba\u03ae \u039b\u03af\u03c1\u03b1 (\xa3)"},
gaem(){return"\u0395\u03c5\u03c1\u03ce (\u20ac)"},
gaeq(){return"\u0394\u03bf\u03bb\u03ac\u03c1\u03b9\u03bf \u0397\u03a0\u0391 ($)"},
gaep(){return"\u0399\u03b1\u03c0\u03c9\u03bd\u03b9\u03ba\u03cc \u0393\u03b5\u03bd (\xa5)"},
gah4(){return"\u03a0\u03c1\u03bf\u03c3\u03b8\u03ae\u03ba\u03b7 \u03c0\u03c1\u03bf\u03c3\u03c9\u03c0\u03b9\u03ba\u03bf\u03cd"},
gah6(){return"\u03a0\u03c1\u03bf\u03c3\u03b8\u03ad\u03c3\u03c4\u03b5 \u03cc\u03bd\u03bf\u03bc\u03b1 \u03ba\u03b1\u03b9 \u03c4\u03b5\u03c4\u03c1\u03b1\u03c8\u03ae\u03c6\u03b9\u03bf PIN \u03b3\u03b9\u03b1 \u03ba\u03ac\u03b8\u03b5 \u03bc\u03ad\u03bb\u03bf\u03c2 \u03c4\u03b7\u03c2 \u03bf\u03bc\u03ac\u03b4\u03b1\u03c2 \u03ce\u03c3\u03c4\u03b5 \u03bf\u03b9 \u03c0\u03b1\u03c1\u03b1\u03b3\u03b3\u03b5\u03bb\u03af\u03b5\u03c2 \u03ba\u03b1\u03b9 \u03bf\u03b9 \u03c0\u03bb\u03b7\u03c1\u03c9\u03bc\u03ad\u03c2 \u03bd\u03b1 \u03b1\u03c0\u03bf\u03b4\u03af\u03b4\u03bf\u03bd\u03c4\u03b1\u03b9 \u03c3\u03b5 \u03b1\u03c5\u03c4\u03bf\u03cd\u03c2."},
gZ_(){return"\u03a0\u03c1\u03bf\u03c3\u03b8\u03ae\u03ba\u03b7 \u039c\u03ad\u03bb\u03bf\u03c5\u03c2 \u03a0\u03c1\u03bf\u03c3\u03c9\u03c0\u03b9\u03ba\u03bf\u03cd"},
gahd(){return"\u0391\u03c6\u03b1\u03af\u03c1\u03b5\u03c3\u03b7 \u039c\u03ad\u03bb\u03bf\u03c5\u03c2 \u03a0\u03c1\u03bf\u03c3\u03c9\u03c0\u03b9\u03ba\u03bf\u03cd;"},
ahc(a){return"\u039f/\u0397 \xab"+a+"\xbb \u03b4\u03b5\u03bd \u03b8\u03b1 \u03bc\u03c0\u03bf\u03c1\u03b5\u03af \u03c0\u03bb\u03ad\u03bf\u03bd \u03bd\u03b1 \u03c3\u03c5\u03bd\u03b4\u03b5\u03b8\u03b5\u03af \u03bc\u03b5 \u03c4\u03bf PIN \u03c4\u03bf\u03c5/\u03c4\u03b7\u03c2. \u039f\u03b9 \u03c0\u03b1\u03bb\u03b9\u03ad\u03c2 \u03c0\u03b1\u03c1\u03b1\u03b3\u03b3\u03b5\u03bb\u03af\u03b5\u03c2/\u03c0\u03bb\u03b7\u03c1\u03c9\u03bc\u03ad\u03c2 \u03c0\u03b1\u03c1\u03b1\u03bc\u03ad\u03bd\u03bf\u03c5\u03bd \u03b1\u03c0\u03bf\u03b4\u03bf\u03c3\u03bc\u03ad\u03bd\u03b5\u03c2 \u03c3\u03b5 \u03b1\u03c5\u03c4\u03cc\u03bd/\u03b1\u03c5\u03c4\u03ae\u03bd."},
gahb(){return"\u0391\u03c6\u03b1\u03af\u03c1\u03b5\u03c3\u03b7"},
