gakR(){return"\u0392\u03ae\u03bc\u03b1\u03c4\u03b1"},
ale(a){var s=null
return A.bV(a,s,this.a,s,"1 \u03bb\u03b5\u03c0\u03c4\u03cc",""+a+" \u03bb\u03b5\u03c0\u03c4\u03ac",s,s)},
gaLg(){return"\u03a3\u03c5\u03bd\u03c4\u03b1\u03b3\u03ad\u03c2"},
